yakit.AutoInitYakit()

# Input your code!

scanTargets = cli.FileOrContent("scanTarget", cli.setRequired(true),cli.setVerboseName("扫描目标"))
targetDescription = cli.String("targetDescription", cli.setRequired(true),cli.setVerboseName("目标描述"))
awvsHost = cli.String("awvsHost", cli.setVerboseName("AWVS 服务器"),cli.setRequired(true),cli.setHelp("设置AWVS访问的url"),cli.setDefault("https://localhost:3443/api/v1"))
apiKey = cli.String("apiKey", cli.setVerboseName("API KEY"),cli.setRequired(true),cli.setHelp("设置AWVS访问的url"))
UA = cli.String("UA", cli.setCliGroup("配置"),cli.setDefault("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.116 Safari/537.36"))
scanProxy = cli.String("scanProxy",cli.setCliGroup("配置"),cli.setHelp("设置扫描代理"))
thread = cli.StringSlice("thread", cli.setCliGroup("配置"),cli.setMultipleSelect(false),cli.setVerboseName("扫描速度"),cli.setSelectOption("sequential", "sequential"),cli.setSelectOption("缓慢", "slow"),cli.setSelectOption("适度", "moderate"),cli.setSelectOption("快速", "fast"),cli.setDefault("moderate"))
scanprofile = cli.StringSlice("scanprofile", cli.setCliGroup("配置"),cli.setMultipleSelect(false),cli.setVerboseName("扫描配置文件"),cli.setSelectOption("Full Scan", "Full Scan"),cli.setSelectOption("Cross-site Scripting", "Cross-site Scripting"),cli.setSelectOption("SQL Injection", "SQL Injection"),cli.setSelectOption("Crawl Only", "Crawl Only"),cli.setDefault("Full Scan"))

cli.check()

# 定义请求头
header = {"Content-Type":"application/json","Accept":"application/json","X-Auth":apiKey}
if awvsHost.EndsWith("/"){awvsHost = awvsHost[:-1]}
scanTargets = str.ParseStringToLines(string(scanTargets)) 

# 调用查询目标接口，通过响应判断key是否正确
checkApiKey = func(){
    url = awvsHost+"/targets"
    res,_, err = poc.Get(url,poc.timeout(5),poc.appendHeaders(header))
    if err != nil{
        yakit.Error("网路检查：AWVS访问失败，请检查配置！")
    }

    if res.GetStatusCode() == 200{
        yakit.Info("KEY检查：成功！")
        return true
    }else{
        yakit.Info("KEY检查：失败！")
        return false
    }
}

# 创建一个组，后续批量导入的目标都放整个组里，组名问当前时间
createGroup = func(){
    body= `{
  "group_id": "306db4e0-7449-4501-b76f-075576fe2d8f",
  "name": "%v",
  "target_count": 0,
  "description": "Yakit 导入",
  "vuln_count": {
    "critical": 0,
    "high": 0,
    "medium": 0,
    "low": 0,
    "info": 0
  }
}`%time.Now().Format("20060102150405")
    url = awvsHost+"/target_groups"
    group_id = ""
    res,_,err = poc.Post(url, poc.timeout(5),poc.appendHeaders(header),poc.replaceBody([]byte(body), false))
    if err != nil {
        yakit.Info("网络检查：添加组失败，请检查网络连接！")
        die(err)
    }
    if res.GetStatusCode() == 201{
        resBody = res.GetBody()
        resBody = json.loads(string(resBody))
        group_id = resBody["group_id"]
        
    }else{
        yakit.Info("响应检查：添加组请求失败！") 
    }
    return group_id
}

# 生成一个导入的目标
newTarget = func(address,description){
    target = make(map[string]var)
    target["address"] = address
    target["description"] = description
    target["type"] = "default"
    target["criticality"] = 30
    return target
}
# 生成批量导入的请求体
addTargetBody = func(group_id){
    body = make(map[string]var)
    targets = []
    groups = []
    groups = append(groups, group_id)
    for _,t = range scanTargets{
        t = str.TrimSpace(t)
        targets = append(targets,newTarget(t,targetDescription))
    }
    body["targets"] = targets
    body["groups"] = groups
    return body
}

#批量导入目标
addAwvsTargets = func(group_id){
    resTargetId = []
    url = awvsHost+"/targets/add"
    body = addTargetBody(group_id)
    body = []byte(json.dumps(body))
    res,_,err = poc.Post(url, poc.timeout(5),poc.appendHeaders(header),poc.replaceBody([]byte(body), false))
        if err != nil {
        yakit.Info("网络检查：添加组失败，请检查网络连接！")
        die(err)
    }
    if res.GetStatusCode() == 200{
        resBodyRaw = res.GetBody()
        resBodyRaw = json.loads(resBodyRaw)
        for _,i = range resBodyRaw["targets"]{
            resTargetId = append(resTargetId, i["target_id"])
        }
    }else{
        yakit.Info("响应检查：添加目标请求失败！") 
    }
    return resTargetId
}

# 获取扫描配置文件ip

getProfile = func(){
    profileId = ""
    url = awvsHost+"/scanning_profiles"
    res,_, err = poc.Get(url, poc.timeout(5),poc.appendHeaders(header))
        if err != nil {
        yakit.Info("网络检查：检查扫描配置文件失败，请检查网络连接！")
        die(err)
    }
    if res.GetStatusCode() == 200{
        resBody = res.GetBody()
        resBody = json.loads(string(resBody))
        for _,i = range resBody["scanning_profiles"]{
            if i["name"] == scanprofile[0]{
                profileId = i["profile_id"]
                break
            }
        }
        
    }else{
        yakit.Info("响应检查：添加组请求失败！") 
    }
    return profileId
}


# 修改目标配置信息
changConf = func(targets){
    body = {
  "scan_speed": "fast",
  "login": { "kind": "none" },
  "ssh_credentials": { "kind": "none" },
  "default_scanning_profile_id": "11111111-1111-1111-1111-111111111111",
  "sensor": false,
  "case_sensitive": "no",
  "limit_crawler_scope": true,
  "excluded_paths": [],
  "authentication": { "enabled": false },
  "proxy": {
    "enabled": false,
    "protocol": "http",
    "address": "127.0.0.1",
    "port": 80
  },
  "custom_headers": [],
  "custom_cookies": [],
  "ad_blocker": true,
  "debug": false,
  "skip_login_form": false,
  "restrict_scans_to_import_files": false,
  "client_certificate_password": "",
  "user_agent": "",
  "issue_tracker_id": "",
  "preseed_mode": "",
  "plugin_instance_id": ""
}
    if scanProxy != ""{
        scanProxy, err = str.ParseStringUrlToUrlInstance(scanProxy)
        if err !=nil{
            yakit.Info("代理检查：代理地址格式错误！")
            die(err)
        }
    body["proxy"]["enabled"] = true
    body["proxy"]["protocol"] = scanProxy.Scheme
    body["proxy"]["address"] = scanProxy.Hostname()
    body["proxy"]["port"] = scanProxy.Port()
    }
    profileId = getProfile()
    if profileId == ""{yakit.Info("配置检查：扫描配置文件获取失败！");os.Exit(0)}
    body["default_scanning_profile_id"] = profileId
    body["user_agent"] = UA
    body["scan_speed"] = thread[0]
    for _,i = range targets{
        url = awvsHost+"/targets/%v/configuration"%i
        res,_,err = poc.Do("PATCH", url, poc.replaceBody([]byte(json.dumps(body)), false),poc.appendHeaders(header))
        if err != nil {
        yakit.Info("网络检查：检查扫描配置文件失败，请检查网络连接！")
        die(err)
        }
        if res.GetStatusCode() != 204{
            yakit.Info("目标修改配置失败！")
        }
    }
    
}


main = func(){
    if !checkApiKey(){os.Exit(0)}
    groupID = createGroup()
    if groupID == ""{
        os.Exit(0)
    }
    targetsID = addAwvsTargets(groupID)
    if len(targetsID)<0{
        os.Exit(0)
    }
    changConf(targetsID)
    yakit.Info("success!!")
}
main()
